// background.js - service worker.
// Owns ONE resilient WebSocket to the local bridge (ws://127.0.0.1:PORT).
// Keeping the socket here (not in the content script) avoids https→ws mixed
// content issues and centralises reconnect / timeout logic.
//
// Contract with content.js: every sendMessage ALWAYS gets a response object,
// even when the bridge is offline. The agentic loop must never hang waiting.
//
// SECURITY (issue #61, fixed in 1.5.6.2): the bridge now requires a per-install
// auth token on every message. The token is generated by the bridge on first
// launch (printed in the terminal, saved to bridge_token.txt next to
// config.json). The user pastes it ONCE into the popup, which stores it in
// chrome.storage.local; this file reads it from storage and adds it to every
// outgoing message. The bridge also rejects WebSocket connections whose
// Origin header isn't a chrome-extension:// or moz-extension:// origin, so a
// random webpage can't drive the bridge either.

const PORT = 17613;
const URL = `ws://127.0.0.1:${PORT}`;

// Chat sites where a ZeroScript provider content script runs. Status pushes go
// to every tab matching these. Add the new provider's URL pattern here (and in
// manifest.json content_scripts + host_permissions) when integrating another AI.
const PROVIDER_URLS = ["https://chat.deepseek.com/*", "https://chatgpt.com/*", "https://chat.openai.com/*", "https://gemini.google.com/*", "https://www.kimi.ai/*", "https://kimi.ai/*", "https://chat.z.ai/*", "https://chat.qwen.ai/*", "https://arena.ai/*", "https://www.meta.ai/*", "https://meta.ai/*"];

const RECONNECT_MIN = 1000;
const RECONNECT_MAX = 5000;
const HEARTBEAT_MS = 10000;
// If no message (incl. pong) arrives within this window while we believe we're
// connected, the socket is half-open: force a reconnect instead of letting
// pending requests slowly time out.
const STALE_SOCKET_MS = 25000;
const REQUEST_TIMEOUT_DEFAULT = 130000; // a bit above the 120s tool timeout

let ws = null;
let connected = false;
let reconnectDelay = RECONNECT_MIN;
let reconnectTimer = null;
let heartbeatTimer = null;
let lastMessageAt = 0; // timestamp of the last frame received from the bridge
let nextId = 1;
const pending = new Map(); // id -> {resolve, timer}
let toolsCache = [];
let mcpAlive = false;
let serversCache = [];
// true/false = a PLACE is loaded and usable in Roblox Studio; null = unknown.
// The MCP process stays alive when Studio is closed or its MCP option is off,
// so this is probed separately (bridge "studio_status").
let studioConnected = null;
// true/false = a Roblox Studio app is connected to the MCP server at all; null =
// unknown. studioApp=true with studioConnected=false means "Studio open but no
// place"; studioApp=false means "Studio closed OR its MCP option disabled".
let studioApp = null;
// true/false = a Roblox Studio WINDOW/PROCESS exists on this machine (checked
// bridge-side via tasklist); null = unknown/old bridge. Distinguishes the two
// studioApp=false sub-cases the UI must word differently: Studio genuinely not
// launched ("open Roblox Studio") vs Studio OPEN but its MCP plugin never
// registered with the bridge - the documented fix for the latter is opening
// Assistant Settings > MCP Servers inside Studio (validated live 3x), which
// "open Roblox Studio" wording completely fails to convey.
let studioProc = null;

// Per-install auth token (issue #61). Loaded from chrome.storage.local on
// service-worker startup AND every time the popup saves a new value. The
// bridge rejects every message whose `token` field doesn't match the value
// in its bridge_token.txt, so without this we can connect (Origin check
// passes for a chrome-extension:// origin) but every call_tool / list_tools
// / add_server is bounced back as auth_error.
let bridgeToken = "";

// Whether the connected bridge has told us it requires the token. Old
// (1.5.6.1 and earlier) bridges don't send `auth_required`, so this stays
// false and we don't show the "paste your token" prompt. New (1.5.6.2+)
// bridges set it on every "connected" frame.
let bridgeAuthRequired = false;

// Auto-handshake (1.5.6.3+): flipped to TRUE for ~2s after we auto-store a
// token from the bridge's welcome frame, so the popup can show a one-line
// "Bridge authenticated ✓" confirmation. Set back to false from the popup
// itself after it shows the line once, so we don't keep re-rendering it on
// every status push. Not persisted - it's a transient UI flag only.
let bridgeAuthJustSet = false;

function log(...a) {
  console.log("[zs-bg]", ...a);
}

// Load the saved token from chrome.storage.local. Stored locally (not sync)
// because the bridge is per-machine - a user with Chrome sync across
// machines has a DIFFERENT bridge_token.txt on each one, so a synced token
// would be wrong on every other machine.
function loadTokenFromStorage() {
  try {
    chrome.storage.local.get(["bridgeToken"], (r) => {
      const v = r && r.bridgeToken;
      if (typeof v === "string") {
        bridgeToken = v.trim();
        log("loaded bridge token from storage (length=" + bridgeToken.length + ")");
      } else {
        bridgeToken = "";
      }
    });
  } catch (e) {
    log("storage.get bridgeToken failed", e);
  }
}
loadTokenFromStorage();

// ── WebSocket lifecycle ─────────────────────────────────────────────────
function connect() {
  if (ws && (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING)) {
    return;
  }
  clearTimeout(reconnectTimer);
  try {
    ws = new WebSocket(URL);
  } catch (e) {
    log("WebSocket ctor failed", e);
    scheduleReconnect();
    return;
  }

  ws.onopen = () => {
    connected = true;
    reconnectDelay = RECONNECT_MIN;
    lastMessageAt = Date.now();
    log("connected to bridge");
    startHeartbeat();
    broadcastStatus();
  };

  ws.onmessage = (ev) => {
    lastMessageAt = Date.now();
    let msg;
    try {
      msg = JSON.parse(ev.data);
    } catch {
      return;
    }
    handleBridgeMessage(msg);
  };

  ws.onclose = () => {
    connected = false;
    mcpAlive = false;
    studioConnected = null;
    studioApp = null;
    studioProc = null;
    serversCache = [];
    stopHeartbeat();
    failAllPending("bridge connection closed");
    broadcastStatus();
    scheduleReconnect();
  };

  ws.onerror = () => {
    // onclose will follow; nothing to do here but avoid an unhandled error.
    try { ws.close(); } catch {}
  };
}

function scheduleReconnect() {
  clearTimeout(reconnectTimer);
  reconnectTimer = setTimeout(connect, reconnectDelay);
  reconnectDelay = Math.min(reconnectDelay * 1.7, RECONNECT_MAX);
}

function startHeartbeat() {
  stopHeartbeat();
  heartbeatTimer = setInterval(() => {
    if (connected) {
      // Half-open socket: the WS still reports OPEN but nothing comes through.
      // The pong (and every other frame) refreshes lastMessageAt; if it has
      // gone stale, drop the dead socket so onclose triggers a reconnect.
      if (lastMessageAt && Date.now() - lastMessageAt > STALE_SOCKET_MS) {
        log("socket stale, forcing reconnect");
        try { ws.close(); } catch {}
        return;
      }
      // Keeps the MV3 service worker alive AND detects a half-open socket.
      send({ type: "ping" }).catch(() => {});
      refreshStudioStatus();
    }
  }, HEARTBEAT_MS);
}

function stopHeartbeat() {
  clearInterval(heartbeatTimer);
  heartbeatTimer = null;
}

// Resolve once the socket is OPEN, or false after `timeout` ms.
function waitForConnection(timeout = 8000) {
  return new Promise((resolve) => {
    if (connected && ws && ws.readyState === WebSocket.OPEN) return resolve(true);
    connect(); // nudge a (re)connection - important after a worker wake-up
    const t0 = Date.now();
    const iv = setInterval(() => {
      if (connected && ws && ws.readyState === WebSocket.OPEN) {
        clearInterval(iv);
        resolve(true);
      } else if (Date.now() - t0 > timeout) {
        clearInterval(iv);
        resolve(false);
      }
    }, 100);
  });
}

// ── request/response over the socket ────────────────────────────────────
async function send(obj, timeout = REQUEST_TIMEOUT_DEFAULT) {
  // The MV3 service worker can be suspended; the first message after a wake-up
  // arrives before the socket has re-opened. Wait for it instead of failing -
  // otherwise Kimi wrongly hears "bridge offline".
  if (!connected || !ws || ws.readyState !== WebSocket.OPEN) {
    await waitForConnection(8000);
  }
  return new Promise((resolve) => {
    if (!connected || !ws || ws.readyState !== WebSocket.OPEN) {
      resolve({ ok: false, kind: "disconnected", error: "bridge not connected" });
      return;
    }
    const id = nextId++;
    // Issue #61: stamp the per-install auth token on EVERY outgoing message.
    // The bridge rejects anything that doesn't carry the right token, so we
    // add it here once and every call site (call_tool, list_tools, ping,
    // studio_status, add_server, remove_server, restart_mcp) inherits the
    // auth for free. A missing/empty token still sends the field - the
    // bridge then sends back auth_error, which the popup surfaces so the
    // user knows to paste the token from the bridge's terminal.
    const payload = { ...obj, id, token: bridgeToken };
    const timer = setTimeout(() => {
      if (pending.has(id)) {
        pending.delete(id);
        resolve({ ok: false, kind: "timeout", error: "bridge did not respond in time" });
      }
    }, timeout);
    pending.set(id, { resolve, timer });
    try {
      ws.send(JSON.stringify(payload));
    } catch (e) {
      clearTimeout(timer);
      pending.delete(id);
      resolve({ ok: false, kind: "disconnected", error: String(e) });
    }
  });
}

// Ask the bridge whether a Roblox Studio instance is actually connected to the
// MCP server. Broadcasts only on change so the UI updates promptly but quietly.
let studioProbing = false;
async function refreshStudioStatus() {
  if (studioProbing || !connected) return;
  studioProbing = true;
  try {
    const r = await send({ type: "studio_status" }, 12000);
    const v = r && r.ok && typeof r.studio === "boolean" ? r.studio : null;
    if (v !== studioConnected) {
      studioConnected = v;
      broadcastStatus();
    }
  } finally {
    studioProbing = false;
  }
}

function handleBridgeMessage(msg) {
  if ("studio" in msg && (typeof msg.studio === "boolean" || msg.studio === null)) {
    studioConnected = msg.studio;
  }
  if ("studio_app" in msg && (typeof msg.studio_app === "boolean" || msg.studio_app === null)) {
    studioApp = msg.studio_app;
  }
  if ("studio_proc" in msg && (typeof msg.studio_proc === "boolean" || msg.studio_proc === null)) {
    studioProc = msg.studio_proc;
  }
  if (msg.type === "studio_status") {
    resolvePending(msg.id, { ok: true, studio: studioConnected });
    broadcastStatus();
    return;
  }
  if (msg.type === "connected") {
    mcpAlive = !!msg.mcp_alive;
    if (Array.isArray(msg.tools)) toolsCache = msg.tools;
    if (Array.isArray(msg.servers)) serversCache = msg.servers;
    // Issue #61: 1.5.6.2+ bridges tell us they require the per-install auth
    // token on every message. Older bridges never include this field - we
    // leave bridgeAuthRequired false so the popup never shows the "paste
    // your token" prompt against a bridge that wouldn't enforce it.
    bridgeAuthRequired = !!msg.auth_required;
    // Auto-handshake (1.5.6.3+): the bridge sends the per-install token IN
    // the welcome frame (the Origin check on the bridge side has already
    // filtered out non-extension origins, so receiving this frame means we
    // ARE the extension the user installed). Auto-store it if (a) we don't
    // have a token yet, OR (b) the bridge's token differs from ours - the
    // latter is the self-heal path: if the user reinstalled the bridge and
    // got a fresh bridge_token.txt, our stored copy is stale and every
    // outgoing message would bounce as auth_error until we re-paste
    // manually. This auto-corrects on the first reconnect.
    if (typeof msg.token === "string" && msg.token && msg.token !== bridgeToken) {
      const prev = bridgeToken;
      try {
        chrome.storage.local.set({ bridgeToken: msg.token }, () => {
          bridgeToken = msg.token;
          // Surface the change in the popup so a user looking at it sees
          // a one-line "Bridge authenticated ✓" status, matching the
          // chosen UX (silent auto-setup with a brief confirmation).
          bridgeAuthJustSet = !prev; // first-time setup, not a re-store
          log("auto-stored bridge token from welcome frame"
              + (prev ? " (replaced stale stored token)" : " (first time)"));
          broadcastStatus();
        });
      } catch (e) {
        log("could not auto-store bridge token from welcome frame:", e);
      }
    }
    broadcastStatus();
    return;
  }
  if (msg.type === "pong") {
    resolvePending(msg.id, { ok: true });
    return;
  }
  if (msg.type === "tools") {
    if (Array.isArray(msg.tools)) toolsCache = msg.tools;
    if (Array.isArray(msg.servers)) serversCache = msg.servers;
    mcpAlive = !!msg.mcp_alive;
    resolvePending(msg.id, { ok: true, tools: toolsCache });
    broadcastStatus();
    return;
  }
  if (msg.type === "tool_result") {
    resolvePending(msg.id, msg.ok
      ? { ok: true, text: msg.text, images: msg.images || [] }
      : { ok: false, kind: msg.kind, error: msg.error });
    return;
  }
  if (msg.type === "mcp_status") {
    mcpAlive = !!msg.alive;
    if (Array.isArray(msg.tools)) toolsCache = msg.tools;
    if (Array.isArray(msg.servers)) serversCache = msg.servers;
    resolvePending(msg.id, { ok: !!msg.ok, alive: msg.alive, error: msg.error });
    broadcastStatus();
    return;
  }
  if (msg.type === "server_changed") {
    // The bridge acks, then restarts itself to reload config.json. The socket
    // will drop right after this - the content script shows a spinner until the
    // reconnect lands and a fresh status arrives.
    resolvePending(msg.id, { ok: !!msg.ok, error: msg.error, restarting: !!msg.restarting });
    return;
  }
  if (msg.type === "auth_error") {
    // Issue #61: the bridge bounced a message back because the token is
    // missing or wrong. Resolve the pending request as an auth failure so
    // the call site surfaces it, AND log loudly so a user looking at the
    // extension's DevTools console sees the most likely fix immediately
    // (paste the bridge's terminal token into the popup). We don't fail ALL
    // pending requests here - just the one whose id matches - so the next
    // call (after the user saves a token) doesn't get spuriously failed.
    log("auth_error from bridge:", msg.error || "(no detail)",
        "- paste the bridge token from the bridge's terminal into the popup");
    resolvePending(msg.id, { ok: false, kind: "auth_error", error: msg.error || "missing or wrong auth token" });
    broadcastStatus();
    return;
  }
  if (msg.type === "error") {
    resolvePending(msg.id, { ok: false, error: msg.error });
    return;
  }
}

function resolvePending(id, value) {
  const p = pending.get(id);
  if (!p) return;
  clearTimeout(p.timer);
  pending.delete(id);
  p.resolve(value);
}

function failAllPending(reason) {
  for (const [, p] of pending) {
    clearTimeout(p.timer);
    p.resolve({ ok: false, kind: "disconnected", error: reason });
  }
  pending.clear();
}

// ── status push to any open DeepSeek tab + popup ─────────────────────────
function statusObj() {
  return {
    type: "zs-status",
    connected, mcpAlive, studio: studioConnected, studioApp, studioProc,
    tools: toolsCache.length, servers: serversCache,
    // Issue #61: surface the token state to the popup so it can show the
    // "paste your bridge token" prompt only when the bridge actually needs
    // one AND we don't have it yet. `hasToken` is whether chrome.storage
    // already has a value (so the user has already done the one-time setup);
    // `authRequired` is whether the connected bridge will bounce messages
    // without it. A user on an old bridge sees no prompt; a user on a new
    // bridge with no token sees the prompt; a user on a new bridge WITH a
    // token sees the regular status only.
    authRequired: bridgeAuthRequired,
    hasToken: !!bridgeToken,
    // Auto-handshake (1.5.6.3+): true briefly after the welcome frame
    // auto-stored the token. The popup uses this to flash a one-line
    // "Bridge authenticated ✓" confirmation. The popup itself resets this
    // flag via a `clear_auth_just_set` message after rendering, so it
    // doesn't keep firing on every status push.
    authJustSet: bridgeAuthJustSet,
  };
}

function broadcastStatus() {
  chrome.runtime.sendMessage(statusObj()).catch(() => {});
  chrome.tabs.query({ url: PROVIDER_URLS }, (tabs) => {
    for (const t of tabs) chrome.tabs.sendMessage(t.id, statusObj()).catch(() => {});
  });
}

// ── messages from content.js / popup.js ─────────────────────────────────
chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  (async () => {
    switch (msg.type) {
      case "status":
        if (!connected) connect(); // self-heal after a worker wake-up
        sendResponse(statusObj());
        break;
      case "list_tools": {
        // Prefer a live refresh; fall back to cache so the loop never stalls.
        // 10s, not 25s: a catalogue request only blocks this long when one of the
        // MCP servers is dead (typically Roblox in a degraded, Blender-only
        // session), and in that exact case we already hold a perfectly good cached
        // catalogue. Waiting the full 25s just froze the boot for no new data.
        const r = await send({ type: "list_tools" }, 10000);
        if (r.ok) sendResponse({ ok: true, tools: r.tools });
        else sendResponse({ ok: toolsCache.length > 0, tools: toolsCache, error: r.error });
        break;
      }
      case "call_tool": {
        const timeout = (msg.timeout || 120000) + 10000;
        const r = await send(
          { type: "call_tool", name: msg.name, arguments: msg.arguments, timeout: msg.timeout },
          timeout
        );
        sendResponse(r);
        break;
      }
      case "restart_mcp": {
        const r = await send({ type: "restart_mcp" }, 30000);
        sendResponse(r);
        break;
      }
      case "add_server": {
        const r = await send({
          type: "add_server", server_id: msg.server_id,
          command: msg.command, args: msg.args, env: msg.env,
        }, 15000);
        sendResponse(r);
        break;
      }
      case "remove_server": {
        const r = await send({ type: "remove_server", server_id: msg.server_id }, 15000);
        sendResponse(r);
        break;
      }
      case "reconnect":
        reconnectDelay = RECONNECT_MIN;
        connect();
        sendResponse({ ok: true });
        break;
      // Auto-handshake (1.5.6.3+): the popup sends this after rendering the
      // one-line "Bridge authenticated ✓" confirmation, so the flag doesn't
      // keep firing on every status push and the line fades out naturally.
      case "clear_auth_just_set":
        bridgeAuthJustSet = false;
        sendResponse({ ok: true });
        break;
      // ── Issue #61: per-install auth token ───────────────────────────────
      // The popup sends `set_token` after the user pastes the value printed
      // in the bridge's terminal. We store it in chrome.storage.local (per-
      // machine, not synced - see loadTokenFromStorage above), update the
      // in-memory copy that send() reads, and broadcast the new status so
      // every open popup and AI tab drops the "paste your token" prompt.
      case "set_token": {
        const t = (msg.token || "").trim();
        // Validate: the bridge writes 32-char hex, but tolerate 16+ hex
        // chars so a hand-typed shorter token doesn't silently fail. Empty
        // means "clear" (handled by clear_token below).
        const isHex = t && allHex(t) && t.length >= 16;
        if (!isHex) {
          sendResponse({ ok: false, error: "token must be at least 16 hex characters (copy it exactly from the bridge's terminal)" });
          break;
        }
        try {
          chrome.storage.local.set({ bridgeToken: t }, () => {
            bridgeToken = t;
            log("saved bridge token to storage (length=" + t.length + ")");
            broadcastStatus();
            sendResponse({ ok: true });
          });
        } catch (e) {
          sendResponse({ ok: false, error: "could not save token: " + String(e) });
        }
        break;
      }
      case "clear_token": {
        try {
          chrome.storage.local.remove("bridgeToken", () => {
            bridgeToken = "";
            log("cleared bridge token from storage");
            broadcastStatus();
            sendResponse({ ok: true });
          });
        } catch (e) {
          sendResponse({ ok: false, error: "could not clear token: " + String(e) });
        }
        break;
      }
      case "get_token": {
        // Read-only probe the popup uses to render its input state.
        sendResponse({
          ok: true,
          hasToken: !!bridgeToken,
          tokenLength: bridgeToken.length,
          // Never send the full token back to the popup over
          // chrome.runtime - the popup ALREADY has it (the user typed it
          // there). We only return enough to render a mask like "••••1234".
          tokenTail: bridgeToken.length >= 4 ? bridgeToken.slice(-4) : "",
        });
        break;
      }
      default:
        sendResponse({ ok: false, error: "unknown message" });
    }
  })();
  return true; // async sendResponse
});

// Hex check for set_token validation. Kept tiny and at module scope so the
// service worker can re-evaluate it on wake-up without rebuilding closures.
function allHex(s) {
  return /^[0-9a-fA-F]+$/.test(s);
}

// Wake/keepalive hooks.
chrome.runtime.onStartup.addListener(connect);
chrome.runtime.onInstalled.addListener(connect);

connect();
